<template><section class="workbench" data-cpf-page="online-deployment-workbench"><header class="header"><div><h1>Online Deployment·Promotion·Rollback</h1><p>Component Runtime 변경을 Preview → 승인/CAS → Durable Delivery → ACK/Drift → Rollback 흐름으로 제어합니다.</p></div><button @click="loadReference">상태 새로고침</button></header><div class="cards"><article class="card"><span>Health</span><strong>{{ text(health,'status','state','health') }}</strong><small>Control Store</small></article><article class="card"><span>Capabilities</span><strong>{{ capabilities.length }}</strong><small>승인 필요 Capability 포함</small></article><article class="card"><span>Runtime State</span><strong>{{ text(status,'status','state','overallStatus') }}</strong><small>{{ environment||'ALL' }} / {{ serviceId||'ALL' }}</small></article></div><form class="filters" @submit.prevent="lookup"><label>Environment<input v-model.trim="environment"></label><label>Service ID<input v-model.trim="serviceId"></label><label>Change ID<input v-model.trim="lookupId"></label><label>Operation ID<input v-model.trim="lookupOperation"></label><button type="submit">결과 조회</button></form><p v-if="error" class="state error">{{ error }}</p><CpfStructuredData v-if="result" class="detail" :value="result" /><article class="panel"><div class="header"><h2>Runtime 변경 계획</h2><button class="primary" :disabled="busy" @click="preview">Preview</button></div><div class="filters"><label>Change Type<select v-model="command.changeType"><option v-for="cap in capabilities" :key="String(cap.changeType??cap.code)" :value="String(cap.changeType??cap.code)">{{ String(cap.changeType??cap.code) }}</option></select></label><label>Expected Version<input v-model.number="command.expectedVersion" type="number" min="0"></label><label>Approval ID<input v-model.trim="command.approvalId"></label><label>Break-glass ID<input v-model.trim="command.breakGlassId"></label><label>Target JSON<textarea v-model="targetJson"></textarea></label><label>Payload JSON<textarea v-model="payloadJson"></textarea></label><label>사유<textarea v-model.trim="command.reason" minlength="10"></textarea></label></div><label class="confirm"><input v-model="confirmed" type="checkbox"> Preview 결과·대상 Snapshot·CAS·승인·Rollback 영향을 확인했습니다.</label><div class="actions"><button class="danger" :disabled="busy||!confirmed||command.reason.length<10" @click="create">{{ approvalRequired ? "변경 승인 요청" : "변경 실행" }}</button><button :disabled="busy||!resultChangeId" @click="openControl('cancel')">취소 승인 요청</button><button class="danger" :disabled="busy||!resultChangeId" @click="openControl('rollback')">Rollback 승인 요청</button></div></article><div v-if="controlAction" class="dialog-backdrop" @click.self="controlAction=null"><form class="dialog" @submit.prevent="executeControl"><h2>{{ controlAction }}</h2><label>Operation ID<input v-model.trim="controlOperationId" required></label><label>사유<textarea v-model.trim="controlReason" minlength="10" required></textarea></label><label class="confirm"><input v-model="controlConfirmed" type="checkbox"> 결과불명 시 Operation ID로 상태를 재조회합니다.</label><div class="actions"><button type="button" @click="controlAction=null">취소</button><button class="danger" :disabled="busy||!controlConfirmed||controlReason.length<10">승인 요청</button></div></form></div></section></template>
<script setup lang="ts">import { computed,onMounted,reactive,ref } from 'vue';import { createRuntimeChange,findRuntimeCapabilities,findRuntimeChange,findRuntimeHealth,findRuntimeOperation,findRuntimeStatus,previewRuntimeChange,requestRuntimeApproval,type JsonMap,type RuntimeChangeCommand } from './api';import { errorMessage,read,text } from './support';const health=ref<JsonMap>({}),status=ref<JsonMap>({}),capabilities=ref<JsonMap[]>([]),environment=ref(''),serviceId=ref(''),lookupId=ref(''),lookupOperation=ref(''),result=ref<JsonMap|null>(null),error=ref(''),busy=ref(false),targetJson=ref('{"environment":"DEV","serviceIds":[]}'),payloadJson=ref('{}'),confirmed=ref(false),controlAction=ref<'cancel'|'rollback'|null>(null),controlReason=ref(''),controlOperationId=ref(''),controlConfirmed=ref(false);const command=reactive<RuntimeChangeCommand>({operationId:'',changeType:'',reason:'',expectedVersion:0,payloadSchemaVersion:1,target:{},payload:{}});const resultChangeId=computed(()=>String(read(result.value,'changeId','change_id')??''));const approvalRequired=computed(()=>{const selected=capabilities.value.find(c=>String(c.code??c.changeType??'')===command.changeType);return selected?.approvalRequired!==false;});function hydrate(){command.operationId=globalThis.crypto?.randomUUID?.()??`op-${Date.now()}`;command.target=JSON.parse(targetJson.value);command.payload=JSON.parse(payloadJson.value)}async function loadReference(){busy.value=true;error.value='';try{const [a,b,c]=await Promise.all([findRuntimeHealth(),findRuntimeStatus(environment.value,serviceId.value),findRuntimeCapabilities()]);health.value=a;status.value=b;capabilities.value=c;if(!command.changeType&&c.length)command.changeType=String(c[0].changeType??c[0].code??'')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}async function lookup(){busy.value=true;error.value='';try{result.value=lookupId.value?await findRuntimeChange(lookupId.value):await findRuntimeOperation(lookupOperation.value)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}async function preview(){busy.value=true;error.value='';try{hydrate();result.value=await previewRuntimeChange({...command})}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}async function create(){busy.value=true;error.value='';try{hydrate();result.value=approvalRequired.value?await requestRuntimeApproval({...command},'RUNTIME_CONTROL_CREATE'):await createRuntimeChange({...command});confirmed.value=false}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}function openControl(action:'cancel'|'rollback'){controlAction.value=action;controlReason.value='';controlOperationId.value=globalThis.crypto?.randomUUID?.()??`op-${Date.now()}`;controlConfirmed.value=false}async function executeControl(){if(!controlAction.value||!resultChangeId.value)return;busy.value=true;error.value='';try{const ownerCommand=controlAction.value==='cancel'?'RUNTIME_CONTROL_CANCEL':'RUNTIME_CONTROL_ROLLBACK';result.value=await requestRuntimeApproval({operationId:controlOperationId.value,changeType:command.changeType,reason:controlReason.value,expectedVersion:command.expectedVersion,payloadSchemaVersion:1,target:{},payload:{}},ownerCommand,resultChangeId.value);controlAction.value=null}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}onMounted(loadReference);</script><style scoped>
.workbench{display:grid;gap:1rem}.header,.actions,.tabs,.pager{display:flex;gap:.65rem;align-items:center;justify-content:space-between;flex-wrap:wrap}.header h1,.header h2{margin:0}.header p{margin:.35rem 0 0;color:#52606d}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:.7rem;align-items:end}.filters label,.dialog label{display:grid;gap:.3rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:.75rem}.card,.panel{border:1px solid #d7dde5;border-radius:.6rem;padding:1rem;background:#fff}.card strong{font-size:1.35rem;display:block}.table-wrap{overflow:auto;border:1px solid #d7dde5;border-radius:.5rem}table{border-collapse:collapse;width:100%;min-width:900px}th,td{padding:.65rem;border-bottom:1px solid #e4e8ed;text-align:left;vertical-align:top}tbody tr{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#f3f6f9}.state{padding:.75rem;border-radius:.4rem;background:#eef3f7}.state.error{background:#fff0f0;color:#a51d1d}.state.warning{background:#fff8dc;color:#715600}.state.success{background:#edf9f0;color:#126b35}.danger{background:#9d1c1c;color:white}.primary{background:#1f5f99;color:white}.detail{white-space:pre-wrap;overflow:auto;max-height:480px;background:#111827;color:#e5e7eb;padding:1rem;border-radius:.5rem}.dialog-backdrop{position:fixed;inset:0;background:#0008;display:grid;place-items:center;z-index:1000}.dialog{width:min(620px,calc(100vw - 2rem));max-height:90vh;overflow:auto;background:#fff;border-radius:.65rem;padding:1.2rem;display:grid;gap:1rem}.dialog textarea{min-height:100px}.confirm{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.muted{color:#68737d}.badge{display:inline-block;padding:.15rem .45rem;border-radius:999px;background:#e9eef5}.links{display:flex;gap:.6rem;flex-wrap:wrap}@media(max-width:720px){.header{display:grid}.actions{justify-content:flex-start}}
</style>
